SELECT
{% if agg_cols %}  {{ agg_cols | join_list_with_prefix('inv') }}, {% endif %}
  eop_agg,
  SUM(planned_inv_cost) AS plnd_inv_eop_cost
FROM {{ project_id }}.{{ dataset_id }}.mondaysmart_planned_subset_daily AS inv
INNER JOIN (
  SELECT
{% if component == 'linechart' %}  {% if agg_cols %}  {{ agg_cols | join_list_with_prefix('''') }}, {% endif %} {% endif %}    MAX(date_id) AS eop_agg
  FROM {{ project_id }}.{{ dataset_id }}.mondaysmart_fiscal_mapping_dl
  WHERE {{ timeline_where_clause }}
{% if component == 'linechart' %}  {% if agg_cols %} GROUP BY {{ agg_cols | join_list_with_prefix('''') }} {% endif %} {% endif %}) AS f
ON f.eop_agg = inv.date_id
WHERE {{ timeline_where_clause.replace("week_id", "inv.week_id").replace("date_id", "inv.date_id") }}
{% if where_clause %}  AND {{ where_clause }}{% endif %}
{% if agg_cols %} GROUP BY {{ agg_cols | join_list_with_prefix('inv') }}, eop_agg{% else %} GROUP BY eop_agg{% endif %}

SELECT
{% if agg_cols %}  {{ agg_cols | join_list_with_prefix('inv') }}, {% endif %}
  eop_agg,
  SUM(inv.store_total_inv_eop_cost) AS store_total_inv_eop_cost_gmroi
FROM {{ project_id }}.{{ dataset_id }}.mondaysmart_sales_subset_daily AS inv
INNER JOIN (
  SELECT
{% if component == 'linechart' %}  {% if agg_cols %}  {{ agg_cols | join_list_with_prefix('''') }}, {% endif %} {% endif %}    MAX(date_id) AS eop_agg
  FROM {{ project_id }}.{{ dataset_id }}.mondaysmart_fiscal_mapping_dl
  WHERE {{ timeline_where_clause }}
{% if component == 'linechart' %}  {% if agg_cols %} GROUP BY {{ agg_cols | join_list_with_prefix('''') }} {% endif %} {% endif %}) AS f
ON f.eop_agg = inv.date_id
WHERE {{ timeline_where_clause.replace("week_id", "inv.week_id").replace("date_id", "inv.date_id") }}
{% if where_clause %}  AND {{ where_clause }}{% endif %}
{% if agg_cols %} GROUP BY {{ agg_cols | join_list_with_prefix('inv') }}, eop_agg{% else %} GROUP BY eop_agg{% endif %}

SELECT
{% if agg_cols %} {{ agg_cols | join_list_with_prefix('inv') }}, {% endif %}
  SUM(inv.sales_qty) AS sales_qty
FROM {{ project_id }}.{{ dataset_id }}.mondaysmart_inventory_subset_daily AS inv
INNER JOIN (
SELECT
{% if component == 'linechart' %}  {% if agg_cols %}  {{ agg_cols | join_list_with_prefix('''') }}, {% endif %} {% endif %}
    MAX(date_id) AS max_date
  FROM {{ project_id }}.{{ dataset_id }}.mondaysmart_fiscal_mapping_dl
  WHERE {{ timeline_where_clause }}
{% if component == 'linechart' %}  {% if agg_cols %} GROUP BY {{ agg_cols | join_list_with_prefix('''') }} {% endif %}{% endif %}
) f
  ON inv.date_id BETWEEN DATE_SUB(f.max_date, INTERVAL 6 DAY) AND f.max_date

{% if where_clause %} AND {{ where_clause }}{% endif %}
{% if agg_cols %} GROUP BY {{ agg_cols | join_list_with_prefix('inv') }}{% endif %}

SELECT
  {% if agg_cols -%}
  {{ agg_cols | join_list_with_prefix('a') }},
  {%- endif %}
  AVG(conversion_val) AS conversion_val
FROM `{{ project_id }}.{{ dataset_id }}.mondaysmart_currency_conversion` c

{% if "".join(agg_cols).strip().__len__() > 0 -%}
CROSS JOIN (
    SELECT {{ agg_cols | join_list_with_prefix('') }}
    FROM `{{ project_id }}.{{ dataset_id }}.mondaysmart_sales_subset_daily`
    WHERE {{ timeline_where_clause }}
      {% if where_clause %} AND {{ where_clause }} {% endif %}
      AND {{ agg_cols[0] }} IS NOT NULL

    UNION DISTINCT

    SELECT {{ agg_cols | join_list_with_prefix('') }}
    FROM `{{ project_id }}.{{ dataset_id }}.mondaysmart_inventory_subset_daily`
    WHERE {{ timeline_where_clause }}
      {% if where_clause %} AND {{ where_clause }} {% endif %}
      AND {{ agg_cols[0] }} IS NOT NULL

    UNION DISTINCT

    SELECT {{ agg_cols | join_list_with_prefix('') }}
    FROM `{{ project_id }}.{{ dataset_id }}.mondaysmart_planned_subset_daily`
    WHERE {{ timeline_where_clause }}
      {% if where_clause %} AND {{ where_clause }} {% endif %}
      AND {{ agg_cols[0] }} IS NOT NULL
) AS a 
{%- endif %}

WHERE {{ timeline_where_clause.replace("week_id", "c.week_id").replace("date_id", "c.date_id") }}
{% if currency_code %}
  AND currency_code = '{{ currency_code }}'
{% endif %} 

{% if agg_cols -%}
GROUP BY {{ agg_cols | join_list_with_prefix('a') }}
{%- endif %}

SELECT
{% if agg_cols %}  {{ agg_cols | join_list_with_prefix('inv') }}, {% endif %}
  eop_agg,
  SUM(planned_receipt_cost) AS plnd_receipt_cost
FROM {{ project_id }}.{{ dataset_id }}.mondaysmart_planned_subset_daily AS inv
INNER JOIN (
  SELECT
{% if component  in ['linechart', 'store-history-inventory-area']  %} 
 {% if agg_cols %}  {{ agg_cols | join_list_with_prefix('''') }}, {% endif %} {% endif %}    
 MAX(date_id) AS eop_agg
  FROM {{ project_id }}.{{ dataset_id }}.mondaysmart_fiscal_mapping_dl
  WHERE {{ timeline_where_clause }}
{% if component  in ['linechart', 'store-history-inventory-area']  %}  {% if agg_cols %} GROUP BY {{ agg_cols | join_list_with_prefix('''') }} {% endif %} {% endif %}) AS f
ON f.eop_agg = inv.date_id
{% if component == 'store-history-inventory-area' and agg_cols %}
  {% for col in agg_cols %}
    AND f.{{ col }} = inv.{{ col }}
  {% endfor %}
{% endif %}
WHERE {{ timeline_where_clause.replace("week_id", "inv.week_id").replace("date_id", "inv.date_id") }}
{% if where_clause %}  AND {{ where_clause }}{% endif %}
{% if agg_cols %} GROUP BY {{ agg_cols | join_list_with_prefix('inv') }}, eop_agg{% else %} GROUP BY eop_agg{% endif %}

SELECT
{% if agg_cols %}  {{ agg_cols | join_list_with_prefix('agg') }}, {% endif %}
  agg.eop_agg,
  SUM(inv1.sales_qty) AS woh_sales_qty
FROM (
SELECT
{% if agg_cols %}  {{ agg_cols | join_list_with_prefix('inv') }}, {% endif %}
  eop_agg
FROM {{ project_id }}.{{ dataset_id }}.mondaysmart_inventory_subset_daily AS inv
INNER JOIN (
  SELECT
{% if component  in ['linechart', 'store-history-inventory-area']  %}  {% if agg_cols %}  {{ agg_cols | join_list_with_prefix('''') }}, {% endif %} {% endif %}    MAX(date_id) AS eop_agg
  FROM {{ project_id }}.{{ dataset_id }}.mondaysmart_fiscal_mapping_dl
  WHERE {{ timeline_where_clause }}
{% if component  in ['linechart', 'store-history-inventory-area']  %}  {% if agg_cols %} GROUP BY {{ agg_cols | join_list_with_prefix('''') }} {% endif %} {% endif %}) AS f
ON f.eop_agg = inv.date_id
{% if component == 'store-history-inventory-area' and agg_cols %}
  {% for col in agg_cols %}
    AND f.{{ col }} = inv.{{ col }}
  {% endfor %}
{% endif %}
WHERE {{ timeline_where_clause.replace("week_id", "inv.week_id").replace("date_id", "inv.date_id") }}
{% if where_clause %}  AND {{ where_clause }}{% endif %}
{% if agg_cols %} GROUP BY {{ agg_cols | join_list_with_prefix('inv') }}, eop_agg{% else %} GROUP BY eop_agg{% endif %}

) AS agg

JOIN
  (select * from
      {{ project_id }}.{{ dataset_id }}.mondaysmart_inventory_subset_daily 
      {% if where_clause %}  WHERE {{ where_clause }}{% endif %})
        AS inv1
  ON DATE(inv1.date_id) BETWEEN DATE_SUB(agg.eop_agg, INTERVAL 6 DAY) AND agg.eop_agg
{% if agg_cols %} GROUP BY {{ agg_cols | join_list_with_prefix('agg') }}, eop_agg{% else %} GROUP BY agg.eop_agg{% endif %}
